479	func (g *Generator) opcodeFromOp(op string) Opcode {
480		switch op {
481		case "+":
482			return OpAdd
483		case "-":
484			return OpSub
485		case "*":
486			return OpMul
487		case "/":
488			return OpDiv
489		case "==":
490			return OpEq
491		case "!=":
492			return OpNe
493		case "<":
494			return OpLt
495		case ">":
496			return OpGt
497		case "<=":
498			return OpLe
499		case ">=":
500			return OpGe
501		default:
502			return OpNoop
503		}
504	}
