506	// genStructDecl generates IR for a struct declaration
507	func (g *Generator) genStructDecl(node *ast.Node) error {
508		if node.Value == "" {
509			return fmt.Errorf("struct declaration must have a name")
510		}
511	
512		name := node.Value
513		fields := []string{}
514	
515		// Extract field names from children
516		for _, field := range node.Children {
517			if field.Kind == ast.NodeFieldDecl {
518				fields = append(fields, field.Value)
519			}
520		}
521	
522		// Store struct definition
523		g.structFields[name] = fields
524	
525		// Calculate struct size (8 bytes per field)
526		size := len(fields) * 8
527	
528		// Save current function context
529		prevFn := g.currentFn
530		g.currentFn = nil // Emit to Main context
531	
532		// Emit OpStructDef instruction
533		g.emit(Instruction{
534			Op:   OpStructDef,
535			Fn:   name,
536			Src1: Operand{IsImm: true, ImmVal: int64(size)},
537		})
538	
539		// Restore function context
540		g.currentFn = prevFn
541	
542		return nil
543	}
544	
545	// genFieldAccess generates IR for a field access expression (obj.field)
546	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
547		if len(node.Children) == 0 {
548			return Operand{}, fmt.Errorf("field access requires object expression")
549		}
550	
551		// Generate IR for object expression
552		objOp, err := g.genExpr(node.Children[0])
553		if err != nil {
554			return Operand{}, err
555		}
556	
557		fieldName := node.Value
558	
559		// Search for field offset in known structs
560		var offset int64
561		found := false
562		for _, fields := range g.structFields {
563			for i, f := range fields {
564				if f == fieldName {
565					offset = int64(i * 8)
566					found = true
567					break
568				}
569			}
570			if found {
571				break
572			}
573		}
574		// If not found, use offset 0 as fallback
575	
576		// Emit OpFieldLoad instruction
577		result := g.newTemp()
578		g.emit(Instruction{
579			Op:   OpFieldLoad,
580			Dest: result,
581			Src1: objOp,
582			Src2: Operand{IsImm: true, ImmVal: offset},
583		})
584	
585		return result, nil
586	}
