3	// CallFrame represents a function call frame in the call stack
4	type CallFrame struct {
5		FnName string
6		Locals map[string]Value
7	}
8	
9	// NewFrame creates a new call frame for a function
10	// It binds the parameters to their corresponding arguments
11	func NewFrame(fnName string, params []string, args []Value) *CallFrame {
12		frame := &CallFrame{
13			FnName: fnName,
14			Locals: make(map[string]Value),
15		}
16	
17		// Bind parameters to arguments
18		for i, paramName := range params {
19			if i < len(args) {
20				frame.Locals[paramName] = args[i]
21			} else {
22				frame.Locals[paramName] = NilVal()
23			}
24		}
25	
26		return frame
27	}
28	
29	// Get retrieves a value from the frame's local variables
30	func (f *CallFrame) Get(name string) (Value, bool) {
31		v, exists := f.Locals[name]
32		return v, exists
33	}
34	
35	// Set stores a value in the frame's local variables
36	func (f *CallFrame) Set(name string, v Value) {
37		f.Locals[name] = v
38	}
