**`replMode()` 구현** (예상 60~80줄):

```go
func replMode() {
    fmt.Println("FreeLang REPL (Phase 4)")
    fmt.Println("Type 'exit' or 'quit' to quit")
    fmt.Println("---")

    scanner := bufio.NewScanner(os.Stdin)
    lineNum := 0

    for {
        fmt.Printf("fl> ")
        if !scanner.Scan() {
            break
        }

        line := strings.TrimSpace(scanner.Text())
        lineNum++

        if line == "" {
            continue
        }
        if line == "exit" || line == "quit" {
            fmt.Println("Bye!")
            break
        }

        replRunLine(line, lineNum)
    }
}

func replRunLine(code string, lineNum int) {
    // Step 1: Parse
    p := parser.New(code)
    prog, err := p.ParseProgram()
    if err != nil {
        fmt.Printf("[line %d] Parse error: %v\n", lineNum, err)
        return
    }

    // Step 2: Generate IR (optimizer 생략으로 빠른 피드백)
    gen := ir.NewGenerator()
    irProg, err := gen.Generate(prog)
    if err != nil {
        fmt.Printf("[line %d] IR error: %v\n", lineNum, err)
        return
    }

    // Step 3: Run VM
    vm := runtime.New(irProg)
    result, err := vm.Run()
    if err != nil {
        fmt.Printf("[line %d] Error: %v\n", lineNum, err)
        return
    }

    // Step 4: 결과 출력 (KindNil이 아닐 때만)
    if result.Kind != runtime.KindNil {
        fmt.Printf("=> %v\n", result)
    }

    // globals 출력 (let 선언 결과 확인)
    for name, val := range vm.DumpGlobals() {
        fmt.Printf("   %s = %v\n", name, val)
    }
}
```

